let lastDictationInstance = null;
let started = false;

export default class Dictation {
    constructor(options) {
        this.options = options;
        lastDictationInstance = this;
    }

    start() {
        started = true;
    }

    read() {
        return this.lastSimulatedText;
    }
}

export function _reset() {
    lastDictationInstance = null;
    started = false;
}

export function _getLastInstance() {
    return lastDictationInstance;
}

export function _wasStarted() {
    return started;
}

export function _simulateReadable(text) {
    if (lastDictationInstance && lastDictationInstance.options.onReadable) {
        lastDictationInstance.lastSimulatedText = text;
        lastDictationInstance.options.onReadable.call(lastDictationInstance);
    }
}

export function _simulateError(err) {
    if (lastDictationInstance && lastDictationInstance.options.onError) {
        lastDictationInstance.options.onError.call(lastDictationInstance, err);
    }
}
